frappe.ui.form.on('Breakfast', {
    refresh(frm) {
        if (frm.is_new()) {
            let current_user = frappe.session.user;
            console.log("Current User:", current_user);

            let currentMonthName = new Date().toLocaleString('default', { month: 'long' });
            console.log("Current Month Name:", currentMonthName);
            frm.set_value('select_month', currentMonthName);

            // Fetch the Employee linked to the current user
            frappe.db.get_value('Employee', { 'user_id': current_user }, ['name', 'employee_name'])
                .then(function(response) {
                    let employee = response.message;
                    console.log("Employee:", employee);
                    if (employee) {
                        // Set the employee field with the Employee ID
                        frm.set_value('employee_id', employee.name);
                        console.log("Employee name:", employee.name);
                    } else {
                        frappe.msgprint({
                            title: __('Warning'),
                            message: __('No Employee record found for the current user. Contact HR or technical team.'),
                            indicator: 'orange'
                        });
                    }
                });
        }
    },

    validate(frm) {
        const dates = [];
        const duplicates = [];

        (frm.doc.breakfast_table || []).forEach(row => {
            if (row.date) {
                // Extract only the date part (YYYY-MM-DD) from the datetime string
                const dateOnly = row.date.split(' ')[0];
                if (dates.includes(dateOnly)) {
                    duplicates.push(dateOnly);
                } else {
                    dates.push(dateOnly);
                }
            }
        });

        if (duplicates.length > 0) {
            frappe.throw(`Duplicate dates found in breakfast table: ${duplicates.join(", ")}`);
        }
    },

    before_save(frm) {
        // Set initial values for total days and subsidy amount in the form
        frm.set_value('current_table_total_days', 0);
        frm.set_value('current_table_total_subsidy_amount', 0);

        // Function to determine the subsidy cap based on the total number of days
        function get_subsidy_cap(total_days) {
            if (total_days < 50) {
                return 700;
            } else if (total_days < 100) {
                return 750;
            } else {
                return 1000;
            }
        }

        // Check if breakfast_table exists in the form
        if (!frm.doc.breakfast_table || frm.doc.breakfast_table.length === 0) {
            frm.set_value('current_table_total_days', 0);
            frm.set_value('current_table_total_subsidy_amount', 0);
        } else {
            // Calculate the total number of rows in breakfast_table
            frm.set_value('current_table_total_days', frm.doc.breakfast_table.length);

            // Initialize variables for subsidy calculation
            let total_subsidy = 0;
            let current_total_days = parseInt(frm.doc.total_days) || 0;

            // Iterate through each row in breakfast_table to calculate subsidies
            frm.doc.breakfast_table.forEach((row, index) => {
                try {
                    // Determine the subsidy cap for the current total days
                    let subsidy_cap = get_subsidy_cap(current_total_days);

                    // Convert row amount to float, default to 0 if invalid
                    let row_amount = parseFloat(row.amount) || 0;

                    // Calculate subsidy for the row as the minimum of row amount and subsidy cap
                    let row_subsidy = Math.min(row_amount, subsidy_cap);
                    total_subsidy += row_subsidy;

                    // Increment total days for the next iteration
                    current_total_days += 1;
                } catch (e) {
                    // Log any errors encountered during row processing
                    frappe.msgprint({
                        title: __('Error'),
                        message: __(`Error processing row ${index + 1}: ${e.message}`),
                        indicator: 'red'
                    });
                }
            });

            // Update form with the calculated total subsidy amount
            frm.set_value('current_table_total_subsidy_amount', total_subsidy);
            // console.log("Total subsidy : ",total_subsidy);
            // console.log("current_total_days : ",current_total_days);
        }
    }
});

