frappe.ui.form.on('Overtime', {
    refresh(frm) {
        // Optional initialization logic
    },
    start_date(frm) {
        waitforinput(frm);
    },
    end_date(frm) {
        waitforinput(frm);
    }
});

let timer;
function waitforinput(frm) {
    if (timer) {
        clearTimeout(timer);
    }

    timer = setTimeout(() => {
        calculate_time_difference(frm);
    }, 2000); // 2-second delay
}

function calculate_time_difference(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        let start_date = new Date(frm.doc.start_date);
        let end_date = new Date(frm.doc.end_date);

        // Validate that end_date is not before start_date
        if (end_date < start_date) {
            frappe.msgprint(__('End Date cannot be before Start Date'));
            frm.set_value('end_date', null);
            frm.set_value('days_difference', '');
            return;
        }

        // Calculate time difference in milliseconds
        let diff_time = end_date - start_date;

        // Convert to days, hours, minutes, seconds
        let days = Math.floor(diff_time / (1000 * 60 * 60 * 24));
        let hours = Math.floor((diff_time % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        let minutes = Math.floor((diff_time % (1000 * 60 * 60)) / (1000 * 60));
        let seconds = Math.floor((diff_time % (1000 * 60)) / 1000);

        // Format the output (e.g., "0 days, 0 hours, 0 minutes, 51 seconds")
        let time_diff_str = '';
        if (days > 0) time_diff_str += `${days} 日${days > 1 ? 's' : ''}, `;
        if (hours > 0 || days > 0) time_diff_str += `${hours} 時間${hours > 1 ? 's' : ''}, `;
        if (minutes > 0 || hours > 0 || days > 0) time_diff_str += `${minutes} 分${minutes > 1 ?'' : ''}, `;
        time_diff_str += `${seconds} 秒${seconds > 1 ? 's' : ''}`;

        // Set the formatted string to a field (e.g., time_difference or days_difference)
        frm.set_value('days_difference', time_diff_str);
    } else {
        frm.set_value('days_difference', '');
    }
}

frappe.ui.form.on('Leave', {
    refresh(frm) {
        // Optional initialization logic
    },
    from_date(frm) {
        calculate_days_difference(frm);
    },
    to_date(frm) {
        calculate_days_difference(frm);
    }
});

function calculate_days_difference(frm) {
    if (frm.doc.from_date && frm.doc.to_date) {
        let start_date = new Date(frm.doc.from_date);
        let end_date = new Date(frm.doc.to_date);

        // Validate that to_date is not before from_date
        if (end_date < start_date) {
            frappe.msgprint(__('To Date cannot be before From Date'));
            frm.set_value('to_date', null);
            frm.set_value('days_difference', 0);
            return;
        }

        // Calculate time difference in milliseconds
        let diff_time = end_date - start_date;

        // Convert to days (round up to include partial days, common in leave systems)
        let days = Math.ceil(diff_time / (1000 * 60 * 60 * 24));

        // Set the number of days to days_difference
        frm.set_value('days_difference', days);
    } else {
        frm.set_value('days_difference', 0);
    }
}

let timerInterval = null;
let current_row_index = null;

frappe.ui.form.on('Support timesheet', {
    refresh(frm) {
        // Add Timer Button
        if (!frm.is_new()) {
            if (frm.doc.timer_status === 'On') {
                frm.add_custom_button('Complete Timer', () => stop_timer(frm));
                start_timer_display(frm);
            } else {
                frm.add_custom_button('Start Timer', () => start_timer(frm));
            }
        }
    }
});

function start_timer(frm) {
    const now = frappe.datetime.now_datetime();

    // Add new row to time_logs table
    const new_row = frm.add_child('time_logs');
    new_row.from_time = now;
    new_row.to_time = '';
    new_row.hours = 0;

    current_row_index = frm.doc.time_logs.length - 1; // Store index of current timer row

    frm.set_value('timer_status', 'On');
    frm.save().then(() => {
        frm.reload_doc();
    });
}

function stop_timer(frm) {
    const now = frappe.datetime.now_datetime();

    if (current_row_index == null || !frm.doc.time_logs[current_row_index]) {
        frappe.msgprint("No running timer found.");
        return;
    }

    const row = frm.doc.time_logs[current_row_index];
    row.to_time = now;

    const from = frappe.datetime.str_to_obj(row.from_time);
    const to = new Date(now);
    const diff_sec = Math.floor((to - from) / 1000);
    const diff_hours = diff_sec / 3600;

    row.hours = diff_hours;

    frm.set_value('timer_status', 'Off');

    frm.save().then(() => {
        if (timerInterval) clearInterval(timerInterval);
        frm.reload_doc();
        current_row_index = null;
    });
}

function start_timer_display(frm) {
    if (
        current_row_index == null ||
        !frm.doc.time_logs[current_row_index] ||
        !frm.doc.time_logs[current_row_index].from_time
    ) {
        return;
    }

    const from = frappe.datetime.str_to_obj(frm.doc.time_logs[current_row_index].from_time);

    timerInterval = setInterval(() => {
        const now = new Date();
        const diff_sec = Math.floor((now - from) / 1000);
        const display = secondsToHHMMSS(diff_sec);

        frappe.show_alert({
            message: `⏱️ Timer: ${display}`,
            indicator: 'blue'
        }, 1);
    }, 1000);
}

function secondsToHHMMSS(seconds) {
    const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
    const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
    const s = Math.floor(seconds % 60).toString().padStart(2, '0');
    return `${h}:${m}:${s}`;
}
